import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { criarServidor } from '../api/servidor.js';

const app = criarServidor();
const server = createServer(app);
let port;

test.before(async () => {
  await new Promise((resolve, reject) => {
    server.listen(0, (err) => {
      if (err) return reject(err);
      port = server.address().port;
      resolve();
    });
  });
});

test.after(async () => {
  server.close();
});

async function reset() {
  await fetch(`http://localhost:${port}/_teste/reset`, { method: 'POST' });
}

test('M4 - certificado: atividade inexistente retorna 404', async () => {
  await reset();
  const res = await fetch(`http://localhost:${port}/atividades/atv_inexistente/certificado`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-Usuario': 'p-carla' }
  });
  assert.equal(res.status, 404);
});
